styles:
.first-tr-line tbody tr:nth-child(1) > * {
    border-top: 3px solid #ffdd00 !important;
    border-bottom: 3px solid #ffdd00 !important;
}
.first-tr-line tbody tr:nth-child(1) > *:first-child {
    border-left: 3px solid #ffdd00 !important;
}
.first-tr-line tbody tr:nth-child(1) > *:last-child {
    border-right: 3px solid #ffdd00 !important;
}
.first-column tr > *:nth-child(2) {
    border-right: 3px solid #ffdd00 !important;
    border-left: 3px solid #ffdd00 !important;
}
.first-column tr:first-child > *:nth-child(2) {
    border-top: 3px solid #ffdd00 !important;
}
.first-column tr:last-child > *:nth-child(2) {
    border-bottom: 3px solid #ffdd00 !important;
}
